136:     bool isDialogOpen = false;
137:     CFArrayRef windowList;
138: 
139:     // loops for max 1 second, breaks if/when dialog is found
140:     for (int index = 0; index <= MAX_NUM_LIKELY_OPEN_WINDOWS; index++) {
141:         windowList = CGWindowListCopyWindowInfo(
142:                 kCGWindowListOptionOnScreenAboveWindow, kCGNullWindowID);
143:         int numberOfWindows = CFArrayGetCount(windowList);
