145:         for (int windowIndex = 0; windowIndex < numberOfWindows; windowIndex++) {
146:             NSDictionary *windowInfo =
147:                     (NSDictionary *)CFArrayGetValueAtIndex(windowList, windowIndex);
148:             NSString *windowOwnerName = windowInfo[(id)kCGWindowOwnerName];
149:             NSNumber *windowLayer = windowInfo[(id)kCGWindowLayer];
150:             NSNumber *windowOwnerPID = windowInfo[(id)kCGWindowOwnerPID];
151: 
152:             if ([windowLayer integerValue] == 0 &&
153:                 [windowOwnerName isEqual:@"universalAccessAuthWarn"]) {
154:                 // make sure the auth window is in the foreground
155:                 NSRunningApplication *authApplication = [NSRunningApplication
156:                         runningApplicationWithProcessIdentifier:[windowOwnerPID
157:                                 integerValue]];
158: 
159:                 [NSRunningApplication.currentApplication
160:                         activateWithOptions:NSApplicationActivateAllWindows];
161:                 [authApplication activateWithOptions:NSApplicationActivateAllWindows];
